  const toggleAllSound=()=>{settings.soundEnabled=!settings.soundEnabled;updateAudio();if(settings.soundEnabled&&settings.musicEnabled&&musicPlayer.src)musicPlayer.play().catch(()=>{});send({action:'settings',...settings});document.querySelectorAll('[data-sound-toggle]').forEach(button=>{button.classList.toggle('muted',!settings.soundEnabled);button.innerHTML=button.classList.contains('icon-only')?(settings.soundEnabled?'🔊':'🔇'):`<span>${settings.soundEnabled?'🔊':'🔇'}</span><b>${settings.soundEnabled?'Sound on':'Sound off'}</b>`;});};
