    mode='modes'; root.innerHTML=`<main class="app study">${brand(true)}<section class="page-content"><div class="deck-heading"><div><div class="eyebrow">${cards.length} cards</div><h1>${escapeHtml(deckTitle)}</h1><p class="sub">Choose a focused way to practise.</p></div><button class="control" id="choose-fields">⇄ Choose fields</button></div><div class="mode-list"><button class="mode-row" data-mode="flashcards"><span>🃏</span><div><h2>Flashcards</h2><p>Review and rate each card at your own pace.</p></div><b>→</b></button><button class="mode-row" data-mode="learn"><span>🧠</span><div><h2>Learn</h2><p>Adaptive questions that revisit your mistakes.</p></div><b>→</b></button><button class="mode-row" data-mode="test"><span>📝</span><div><h2>Test</h2><p>Check your knowledge with a quick mixed test.</p></div><b>→</b></button><button class="mode-row" data-mode="match"><span>⚡</span><div><h2>Match</h2><p>Pair terms and answers against the clock.</p></div><b>→</b></button><button class="mode-row" data-mode="shuffle"><span>🔤</span><div><h2>Letter Shuffle</h2><p>Unscramble shuffled answers using the card prompt.</p></div><b>→</b></button><button class="mode-row" data-mode="memory"><span>🧩</span><div><h2>Memory</h2><p>Flip tiles and remember where each matching pair is.</p></div><b>→</b></button></div></section></main>`;
