  const letterShuffle=()=>{const eligible=cards.filter(card=>{const answer=textOnly(card.definition).trim(),letters=answer.replace(/[^A-Za-zÀ-ÿ]/g,'');return !card.imageOcclusion&&letters.length>=3&&letters.length<=28&&answer.split(/\s+/).length<=5;}),sample=shuffle([...eligible]).slice(0,Math.min(10,eligible.length));let q=0,score=0,combo=0,bestCombo=0;const scramble=value=>value.split(/(\s+)/).map(part=>{if(/^\s+$/.test(part)||part.length<3)return part;let mixed=part;for(let tries=0;tries<8&&normalise(mixed)===normalise(part);tries++)mixed=shuffle([...part]).join('');return mixed;}).join('');root.innerHTML=studyHeader('Letter Shuffle','<div class="game-head-stats"><div class="timer">Unscramble 10</div>'+comboMarkup(0)+'</div>')+'<div class="progress-track"><div class="progress" id="shuffle-progress"></div></div><div id="stage"></div></main>';wireBack();const show=()=>{if(!sample.length){root.querySelector('#stage').innerHTML='<div class="empty"><h2>No suitable short answers</h2><p>Letter Shuffle uses answers up to 28 letters and five words.</p><button class="control" id="modes">Return to modes</button></div>';root.querySelector('#modes').onclick=modeScreen;return;}if(q>=sample.length){if(score===sample.length)awardXP(25,'Perfect Shuffle');playEffect('round');root.querySelector('#stage').innerHTML=`<div class="match-results"><div class="trophy">🔤</div><div class="eyebrow">Shuffle complete</div><h2>${score} of ${sample.length} solved</h2><p>Best combo: ${bestCombo} · ${score===sample.length?'Perfect score! +25 XP':'Keep building that combo.'}</p><div class="controls"><button class="control primary" id="again">Shuffle again</button><button class="control" id="modes">Return to modes</button></div></div>`;root.querySelector('#again').onclick=letterShuffle;root.querySelector('#modes').onclick=modeScreen;return;}const card=sample[q],answer=textOnly(card.definition).trim(),jumbled=scramble(answer);root.querySelector('#shuffle-progress').style.width=`${q/sample.length*100}%`;root.querySelector('#stage').innerHTML=`<div class="activity game-activity shuffle-card"><div class="counter">Puzzle ${q+1} of ${sample.length}</div><div class="prompt">${cleanStudyContent(card.term)}</div><div class="shuffled-answer">${escapeHtml(jumbled)}</div><input class="answer-input" id="shuffle-answer" placeholder="Unscramble the answer…" autocomplete="off"><div class="answer-actions"><button class="control" id="shuffle-hint">Hint</button><button class="control" id="shuffle-skip">Skip</button><button class="control primary" id="shuffle-check">Check</button></div><div class="hint-text" id="shuffle-hint-text"></div><div id="shuffle-feedback"></div></div>`;const finish=skipped=>{const input=root.querySelector('#shuffle-answer'),ok=!skipped&&smartEqual(input.value,answer);if(ok){score++;combo++;bestCombo=Math.max(bestCombo,combo);awardXP(5,'Shuffle correct',combo>=3?2:0);}else combo=0;const comboEl=root.querySelector('.study-head .combo-pill');if(comboEl)comboEl.outerHTML=comboMarkup(combo);playEffect(ok?'correct':'wrong');input.disabled=true;root.querySelector('#shuffle-check').disabled=true;root.querySelector('#shuffle-skip').disabled=true;root.querySelector('#shuffle-feedback').innerHTML=`<div class="feedback ${ok?'correct':'wrong'}"><b>${ok?'Solved!':'Answer'}</b><div>${cleanStudyContent(card.definition)}</div><button class="control primary" id="shuffle-next">Next</button></div>`;root.querySelector('#shuffle-next').onclick=()=>{q++;show();};};root.querySelector('#shuffle-hint').onclick=()=>root.querySelector('#shuffle-hint-text').textContent=makeHint(answer);root.querySelector('#shuffle-check').onclick=()=>finish(false);root.querySelector('#shuffle-skip').onclick=()=>finish(true);root.querySelector('#shuffle-answer').onkeydown=e=>{if(e.key==='Enter')finish(false);};root.querySelector('#shuffle-answer').focus();};show();};

  const memoryGame=()=>{const pairs=shuffle([...cards]).slice(0,Math.min(6,cards.length));let first=null,lock=false,remaining=pairs.length,moves=0,combo=0,bestCombo=0;const items=shuffle(pairs.flatMap(c=>[{id:c.id,kind:'term',html:cleanStudyContent(c.term)},{id:c.id,kind:'definition',html:cleanStudyContent(c.definition)}]));root.innerHTML=studyHeader('Memory',comboMarkup(0))+'<div id="stage"><div class="memory-grid">'+items.map((x,i)=>`<button class="memory-tile" data-id="${x.id}" data-kind="${x.kind}" data-key="${i}"><span class="memory-cover">?</span><span class="memory-content">${x.html}</span></button>`).join('')+'</div></div></main>';wireBack();const updateCombo=()=>{const holder=root.querySelector('.study-head .combo-pill');if(holder)holder.outerHTML=comboMarkup(combo);};root.querySelectorAll('.memory-tile').forEach(tile=>tile.onclick=()=>{if(lock||tile.classList.contains('matched')||tile===first)return;tile.classList.add('flipped');if(!first){first=tile;return;}moves++;if(first.dataset.id===tile.dataset.id&&first.dataset.kind!==tile.dataset.kind){first.classList.add('matched');tile.classList.add('matched');first=null;remaining--;combo++;bestCombo=Math.max(bestCombo,combo);awardXP(4,'Memory match',combo>=3?2:0);playEffect('match');updateCombo();if(!remaining){const perfect=moves===pairs.length;awardXP(perfect?30:15,perfect?'Perfect Memory':'Memory complete');playEffect('complete');setTimeout(()=>{root.querySelector('#stage').innerHTML=`<div class="match-results"><div class="trophy">🧩</div><div class="eyebrow">Memory complete</div><h2>${moves} moves</h2><p>Best combo: ${bestCombo} ${perfect?'· Perfect game +30 XP':''}</p><div class="controls"><button class="control primary" id="again">Play again</button><button class="control" id="modes">Return to modes</button></div></div>`;root.querySelector('#again').onclick=memoryGame;root.querySelector('#modes').onclick=modeScreen;},350);}return;}combo=0;updateCombo();playEffect('wrong');lock=true;const old=first;setTimeout(()=>{old.classList.remove('flipped');tile.classList.remove('flipped');first=null;lock=false;},700);});};


  let showMatchTimer=true,matchPairCount=6;
  const matchSetup=()=>{root.innerHTML=studyHeader('Match settings')+`<div class="settings-card match-settings-card"><label class="setting-row"><span><b>Show timer</b><small>Display your live completion time</small></span><input type="checkbox" id="match-timer" checked></label><div class="match-size-setting"><div><b>Number of pairs</b><small>Choose a board size. 6 is best with images; 9 is balanced; 12 works best for text-only cards.</small></div><div class="match-size-options"><button class="size-choice selected" data-pairs="6"><b>6</b><small>Image friendly</small></button><button class="size-choice" data-pairs="9"><b>9</b><small>Balanced</small></button><button class="size-choice" data-pairs="12"><b>12</b><small>Text only</small></button></div></div><button class="control primary" id="start-match">Start Match</button></div></main>`;wireBack();root.querySelectorAll('.size-choice').forEach(btn=>btn.onclick=()=>{root.querySelectorAll('.size-choice').forEach(x=>x.classList.remove('selected'));btn.classList.add('selected');matchPairCount=+btn.dataset.pairs;});root.querySelector('#start-match').onclick=()=>{showMatchTimer=root.querySelector('#match-timer').checked;match();if(!showMatchTimer)root.querySelector('#timer')?.classList.add('hidden');};};
  const match=()=>{const pairs=shuffle([...cards]).slice(0,Math.min(matchPairCount,cards.length));let selected=null,remaining=pairs.length,startTime=Date.now(),combo=0,bestCombo=0;root.innerHTML=studyHeader('Match','<div class="game-head-stats"><div class="timer" id="timer">0.0s</div>'+comboMarkup(0)+'</div>')+'<div id="stage"></div></main>';wireBack();if(!showMatchTimer)setTimeout(()=>root.querySelector('#timer')?.classList.add('hidden'),0);const items=shuffle(pairs.flatMap(c=>[{id:c.id,kind:'term',html:cleanStudyContent(c.term)},{id:c.id,kind:'definition',html:cleanStudyContent(c.definition)}]));root.querySelector('#stage').innerHTML=`<div class="match-grid match-count-${pairs.length}">${items.map((x,i)=>`<button class="match-tile" data-id="${x.id}" data-kind="${x.kind}" data-key="${i}"><div class="match-content">${x.html}</div></button>`).join('')}</div><div id="match-done"></div>`;const timer=setInterval(()=>{const el=root.querySelector('#timer');if(el)el.textContent=`${((Date.now()-startTime)/1000).toFixed(1)}s`;else clearInterval(timer);},250);root.querySelectorAll('.match-tile').forEach(tile=>{tile.classList.toggle('has-media',!!tile.querySelector('img,svg'));tile.onclick=()=>{if(!selected){selected=tile;tile.classList.add('selected');return;}if(selected===tile){selected.classList.remove('selected');selected=null;return;}if(selected.dataset.id===tile.dataset.id&&selected.dataset.kind!==tile.dataset.kind){selected.classList.add('matched');tile.classList.add('matched');remaining--;combo++;bestCombo=Math.max(bestCombo,combo);awardXP(4,'Match pair',combo>=3?2:0);playEffect('match');const comboEl=root.querySelector('.combo-pill');if(comboEl)comboEl.outerHTML=comboMarkup(combo);if(!remaining){clearInterval(timer);const seconds=+((Date.now()-startTime)/1000).toFixed(1),oldRecord=data.matchRecord==null?null:+data.matchRecord,isRecord=oldRecord==null||seconds<oldRecord,difference=oldRecord==null?null:Math.abs(oldRecord-seconds).toFixed(1);if(isRecord){data.matchRecord=seconds;send({action:'matchRecord',deck:data.deck,seconds});}awardXP(bestCombo===pairs.length?25:12,bestCombo===pairs.length?'Perfect Match':'Match complete');playEffect('complete');root.querySelector('#stage').innerHTML=`<div class="match-results"><div class="trophy">${isRecord?'🏆':'🎉'}</div><div class="eyebrow">Match complete</div><h2>${isRecord?'New record!':'Nicely matched!'}</h2><div class="result-time">${seconds.toFixed(1)}s</div><p>${pairs.length} pairs · Best combo: ${bestCombo} · ${bestCombo===pairs.length?'Perfect match! ':''}${oldRecord==null?'Your first record has been saved.':isRecord?`You beat your previous best by ${difference}s!`:`Personal best: ${oldRecord.toFixed(1)}s · ${difference}s away`}</p><div class="controls"><button class="control primary" id="again">Play again</button><button class="control" id="modes">Return to modes</button></div></div>`;root.querySelector('#again').onclick=match;root.querySelector('#modes').onclick=modeScreen;}}else{combo=0;const comboEl=root.querySelector('.combo-pill');if(comboEl)comboEl.outerHTML=comboMarkup(combo);selected.classList.add('wrong-tile');tile.classList.add('wrong-tile');setTimeout(()=>{selected?.classList.remove('wrong-tile','selected');tile.classList.remove('wrong-tile');selected=null;},380);return;}selected=null;};});};

  document.addEventListener('keydown',e=>{
    const tag=(e.target?.tagName||'').toLowerCase(),typing=tag==='input'||tag==='textarea'||tag==='select';
    if(mode==='flashcards'){
      if(e.code==='Space'&&!typing){e.preventDefault();root.querySelector('#flip')?.click();}
      if(e.key==='ArrowRight'&&!typing)root.querySelector('#next')?.click();
      if(e.key==='ArrowLeft'&&!typing)root.querySelector('#prev')?.click();
      if(['1','2','3','4'].includes(e.key)&&!typing&&flipped){e.preventDefault();root.querySelector(`.rating[data-ease="${e.key}"]`)?.click();}
      return;
    }
    if(!typing&&(e.key==='Enter'||e.key==='ArrowRight'||e.key.toLowerCase()==='n')){
      const next=root.querySelector('#continue:not(:disabled),#shuffle-next:not(:disabled),#next-round:not(:disabled)');
      if(next){e.preventDefault();next.click();return;}
    }
    if(e.key==='1'){root.querySelector('[data-value="true"]:not(:disabled)')?.click();root.querySelector('[data-test-value="true"]:not(:disabled)')?.click();}
    if(e.key==='2'){root.querySelector('[data-value="false"]:not(:disabled)')?.click();root.querySelector('[data-test-value="false"]:not(:disabled)')?.click();}
  });
  window.vanillaReceive=next=>{data=next;settings={...settings,...(next.settings||{})};applySettings();updateAudio();if(next.view==='study'){cards=[...(next.cards||[])];fieldMapping={term:next.fieldMapping?.term||'',definition:next.fieldMapping?.definition||''};deckTitle=next.displayDeck||(next.deck||'').split('::').pop();cleanCache.clear();applyFieldMapping();index=0;}renderCurrent();};
  renderCurrent();
